request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
unary-005

Cluster Arity:
1

Cluster Members:
[
  {
    "name": "FORMALIZES_CONSTRAINTS_AS_CHECKABLE_CONDITIONS",
    "definition": "The reasoning converts requirements or preferences stated in prose into explicit, mechanically checkable conditions — such as numeric thresholds, minimum performance factors, size limits, bounds, admissible ranges, or excluded intervals — against which candidate solutions or produced artifacts can be accepted or rejected.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning text that restates the stated requirements as testable acceptance conditions, thresholds, or admissible ranges."
      }
    ],
    "assertion_conditions": [
      "The reasoning states at least one explicit acceptance or admissibility condition attributable to the stated requirements, such as a numeric tolerance, a minimum performance factor, a size limit, a bound, or an admissible range.",
      "The condition is precise enough to accept or reject a candidate solution or produced artifact, or to judge its compliance."
    ],
    "exclusion_conditions": [
      "The reasoning only repeats the original requirement wording without turning it into a condition that can be evaluated against a candidate solution or artifact.",
      "The reasoning merely lists preferences or observations without deriving any acceptance or admissibility condition.",
      "The reasoning only reports the result of an already executed check rather than stating a condition to be met."
    ]
  },
  {
    "name": "OPERATIONALIZES_UNDERSPECIFIED_REQUIREMENT",
    "definition": "The reasoning recognizes an ambiguous or underspecified aspect of a requirement and commits to a concrete, executable interpretation — such as which fields to process, which filter condition to apply, which metric to compute, or which tool to use — that can guide the procedure.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that resolves an ambiguity or underspecification into an operational interpretation."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies an ambiguity, an alternative reading, or an underspecified aspect of the requirement.",
      "The reasoning commits to a concrete operational definition or procedure rather than leaving the ambiguity open.",
      "The selected interpretation is specific enough to determine which data, condition, metric, or tool will be used."
    ],
    "exclusion_conditions": [
      "The requirement is already fully specified and the reasoning only restates it.",
      "The reasoning notes an ambiguity but does not resolve it into an operational definition.",
      "The reasoning supplies procedural detail that is not tied to interpreting the requirement."
    ]
  },
  {
    "name": "IDENTIFIES_SPECIFICATION_AMBIGUITY",
    "definition": "The reasoning explicitly flags that a requirement, specification, or instruction admits multiple interpretations or lacks sufficient detail for a unique action.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text identifying the ambiguous requirement, field, rule, or instruction."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a specific requirement, field, rule, or instruction that is ambiguous, underspecified, or open to multiple readings.",
      "The reasoning signals uncertainty or the existence of competing possible interpretations."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates requirements without acknowledging any ambiguity.",
      "The reasoning makes a choice without noting that an ambiguity or interpretation issue exists."
    ]
  },
  {
    "name": "RESOLVES_INSTRUCTION_CONFLICT",
    "definition": "The reasoning recognizes that two applicable instructions, rules, or requirements pull in conflicting directions for the current step, and explicitly justifies how the tension is settled, for example by prioritizing one, interpreting their scopes so they do not overlap, or choosing a reading that keeps both acceptable.",
    "parameters": [
      {
        "name": "conflict_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that names the competing instructions or constraints and states how the conflict is resolved."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least two instructions, constraints, or requirements that are both applicable to the current action and are in tension or conflict.",
      "The reasoning explicitly states a resolution of that tension, such as a prioritization, a scope interpretation that removes the overlap, or a compromise reading that keeps both compatible."
    ],
    "exclusion_conditions": [
      "The reasoning follows an instruction or constraint without acknowledging any competing instruction or requirement.",
      "The reasoning acknowledges a tension or contradiction but leaves it unresolved and proceeds without justification.",
      "The competing considerations are not both applicable to the action being performed.",
      "The reasoning resolves a conflict between two versions or facts about an artifact or value rather than between applicable instructions or requirements."
    ]
  },
  {
    "name": "DECLINES_OPTIONAL_CHANGE_FOR_REQUIREMENT_FIDELITY",
    "definition": "The reasoning weighs an optional enhancement, extra field, or deviation that is not demanded by the stated requirements, and explicitly decides against it in order to stay faithful to what was actually asked, avoiding scope creep or unintended departure from the specification.",
    "parameters": [
      {
        "name": "fidelity_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that considers an optional enhancement or deviation and explicitly rejects it to preserve fidelity to the stated requirements."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a concrete optional enhancement, additional element, or alternative that is not required by the stated requirements.",
      "The reasoning explicitly states that the option is unnecessary, unrequested, or could conflict with the stated requirements.",
      "The reasoning explicitly decides not to apply the optional change."
    ],
    "exclusion_conditions": [
      "The reasoning simply never considers the optional change, so nothing is weighed and rejected.",
      "The reasoning adopts the optional enhancement rather than declining it.",
      "The optional change is rejected for a reason unrelated to fidelity to the stated requirements, such as performance or convenience.",
      "The reasoning decides against an approach because a technical constraint or unavailable capability blocks it rather than because the change would exceed the requirements."
    ]
  }
]

Previously Generated Predicate Names:
["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY",
  "definition": "The reasoning explicitly interprets a stated requirement, specification, rule, or instruction so as to establish what is required, admissible, or in scope for a candidate action or artifact. This includes clarifying or resolving ambiguity or underspecification, deriving checkable acceptance conditions, committing to a concrete operational reading, justifying a resolution of competing instructions, or refusing an unrequested deviation to preserve fidelity. The interpretation is grounded in the stated requirements and provides a basis for judging, guiding, or constraining the action or artifact.",
  "parameters": [
    {
      "name": "requirement_interpretation_reasoning",
      "type": "reasoning",
      "description": "The reasoning text that explicitly engages with a stated requirement, specification, rule, or instruction to clarify its meaning, scope, constraints, conflicts, operational interpretation, or fidelity implications."
    }
  ],
  "assertion_conditions": [
    "The reasoning explicitly refers to at least one stated requirement, specification, rule, or instruction and addresses its meaning, scope, application, or satisfaction rather than merely restating it.",
    "The reasoning performs at least one observable requirement-interpretation act: identifying an ambiguity, underspecification, or competing-instruction conflict; deriving an explicit checkable acceptance or admissibility condition; committing to a concrete operational interpretation of an underspecified aspect; stating a justified resolution of an instruction conflict; or explicitly rejecting an unrequested optional change to preserve requirement fidelity.",
    "The reasoning identifies the affected requirement element and either the resulting condition, choice, resolution, or scope boundary, or the specific ambiguity or conflict that requires interpretation, so that admissibility, compliance, or the next action can be assessed."
  ],
  "exclusion_conditions": [
    "The reasoning only repeats or paraphrases the stated requirement verbatim without addressing ambiguity, constraints, conflict, operational meaning, or scope fidelity.",
    "The reasoning merely lists preferences, observations, or procedural steps that are not tied to interpreting the stated requirements.",
    "The reasoning reports that a check was performed or states a result without expressing the condition, interpretation, ambiguity, conflict resolution, or scope decision that governs admissibility.",
    "The reasoning only notes a generic uncertainty without naming a specific requirement, specification, rule, field, or instruction affected.",
    "When the only candidate act is rejecting a change, the rejection is based solely on performance, convenience, or technical impossibility rather than fidelity to the stated requirements."
  ]
}

